  1277  void Flow::updateProtocol(ndpi_protocol proto_id) {
  1278    /* NOTE: in order to avoid inconsistent states, only overwrite the
  1279     * protocools if UNKNOWN. */
  1280    if (ndpiDetectedProtocol.master_protocol == NDPI_PROTOCOL_UNKNOWN)
  1281      ndpiDetectedProtocol.master_protocol = proto_id.master_protocol;
  1282
  1283    if ((ndpiDetectedProtocol.app_protocol == NDPI_PROTOCOL_UNKNOWN) ||
  1284        (/*
  1285           Update the protocols when adding a subprotocol, not when things
  1286           are totally different
  1287         */
  1288         (ndpiDetectedProtocol.master_protocol ==
  1289          ndpiDetectedProtocol.app_protocol) &&
  1290         (ndpiDetectedProtocol.app_protocol != proto_id.app_protocol)))
  1291      ndpiDetectedProtocol.app_protocol = proto_id.app_protocol;
  1292
  1293    if (ndpiDetectedProtocol.master_protocol == ndpiDetectedProtocol.app_protocol)
  1294      ndpiDetectedProtocol.master_protocol = NDPI_PROTOCOL_UNKNOWN;
  1295
  1296    ndpiDetectedProtocol.protocol_by_ip = proto_id.protocol_by_ip;
  1297
  1298    /* NOTE: only overwrite the category if it was not set.
  1299     * This prevents overwriting already determined category (e.g. by IP or Host)
  1300     */
  1301    if (ndpiDetectedProtocol.category == NDPI_PROTOCOL_CATEGORY_UNSPECIFIED)
  1302      ndpiDetectedProtocol.category = proto_id.category;
  1303  }
